// Native bindings for the 1.6.5 additions. Waveform details are independently
// exercised by OutputTriggerTests, MxModGateTests and MidiMxTests.
void firmware165RackTests(){
    using M=Metropolix;using namespace metrobackup;
    static_assert(M::FORMAT34_NUM_PARAMS==787 && M::MIDI_MX_CHANNEL==787 && M::MIDI_MX_OUTPUT==788 && M::NUM_PARAMS==789,"two global MIDI settings append after every released parameter");
    static_assert(M::SNAPSHOT_PARAMS==522 && M::PRESET_FORMAT==12,"new route semantics version the unchanged musical tuple");
    require(M::presetIndex(M::MIDI_MX_CHANNEL)<0 && M::presetIndex(M::MIDI_MX_OUTPUT)<0,"MIDI MX settings stay outside musical presets");
    auto* driver=new MidiTestDriver;midi::addDriver(24065,driver);auto& packets=driver->output.messages;
    Module::ProcessArgs args{};args.sampleRate=48000;args.sampleTime=1.f/48000;
    auto make=[&]{auto m=std::unique_ptr<M>(new M);m->midiOutput.setDriverId(24065);m->midiOutput.setDeviceId(0);for(int k=0;k<2;++k){m->params[M::ctrlParam(k,M::CTRL_DESTINATION)].setValue(metro::CtrlNone);m->params[M::midiTrackParam(k,M::MIDI_CHANNEL)].setValue(0);}for(int l=0;l<8;++l)m->params[M::midiModParam(l,0)].setValue(0);return m;};
    auto frames=[&](M& m,int n){for(int i=0;i<n;++i){m.process(args);++args.frame;}};
    // Exercise actual Rack A/B cable endpoints, including stopped Stage Player.
    for(int rate:{44100,48000,96000}){
        args.sampleRate=rate;args.sampleTime=1.f/rate;auto m=make();m->params[M::RUN].setValue(0);m->params[M::CV_OUT_DELAY].setValue(0);m->params[M::OUTPUT_SOURCE_A].setValue(38);m->params[M::OUTPUT_SOURCE_B].setValue(39);
        for(int t=0;t<2;++t){m->params[M::stageParam(t,2,M::CV)].setValue(5);m->params[M::stageParam(t,2,M::PROBABILITY)].setValue(0);}m->params[M::GATES+2].setValue(metro::Rest);frames(*m,64);
        for(int t=0;t<2;++t){m->selectedTrack.store(t);m->loopyCommand.store(1u<<2);int high=0,other=0;for(int f=0;f<int(rate*.01);++f){frames(*m,1);high+=m->outputs[M::A_OUT+t].getVoltage()>0;other+=m->outputs[M::A_OUT+1-t].getVoltage()>0;}if(high!=int(std::ceil(.005*rate-1e-9)) || other)std::cerr<<"native trigger rate="<<rate<<" track="<<t<<" high="<<high<<" other="<<other<<"\n";require(high==int(std::ceil(.005*rate-1e-9)) && other==0,"native A/B Mod Trigs deliver a full5ms from the selected Stage Player with independent track binding");m->loopyCommand.store(0);frames(*m,64);}
    }
    // New modes also traverse the real reciprocal expander message and jacks.
    for(int rate:{44100,48000,96000}){
        args.sampleRate=rate;args.sampleTime=1.f/rate;auto m=make();Mx child;m->id=875;child.id=876;m->model=modelMetropolix;child.model=modelMX;m->rightExpander.module=&child;child.leftExpander.module=m.get();m->readSettings();m->sequencer.running=true;
        auto frame=[&]{m->processMx(args,true);child.process(args);if(child.leftExpander.messageFlipRequested){std::swap(child.leftExpander.producerMessage,child.leftExpander.consumerMessage);child.leftExpander.messageFlipRequested=false;}};
        m->params[M::MX_MODE].setValue(metro::MxModGate);for(int l=0;l<8;++l)m->sequencer.modulation.outputs[l]=l%2?1.499f:1.5f;frame();frame();for(int l=0;l<8;++l)require(child.outputs[l].getVoltage()==(l%2?0.f:5.f),"native MX Mod Gate maps every audible MOD lane to its actual expander jack");
        m->params[M::MX_MODE].setValue(metro::MxModTrig);m->sequencer.modulation.outputs.fill(0);frame();frame();m->sequencer.modulation.outputs.fill(5);std::array<int,8> highs{};int width=int(std::ceil(.005*rate-1e-9));for(int f=0;f<width+4;++f){frame();for(int l=0;l<8;++l)highs[l]+=child.outputs[l].getVoltage()>0;}for(int l=0;l<8;++l)require(highs[l]==width,"native MX Mod Trig preserves a full5ms through the one-sample expander link at every sample rate");
        m->rightExpander.module=nullptr;child.leftExpander.module=nullptr;
    }
    args.sampleRate=48000;args.sampleTime=1.f/48000;
    // Call the native MX binding with controlled audible lane voltages. No MX
    // child is present; this also isolates it from ordinary per-lane MIDI CCs.
    {
        auto m=make();require(!m->rightExpander.module,"MIDI MX integration fixture has no expander");m->params[M::MIDI_MX_CHANNEL].setValue(3);m->params[M::MIDI_MX_OUTPUT].setValue(0);m->params[M::MX_MODE].setValue(metro::MxModGate);
        for(int l=0;l<8;++l){m->params[M::modParam(l,M::MOD_TYPE)].setValue(metro::ModUnipolar);m->params[M::modParam(l,M::MOD_VALUE)].setValue(2.5f);}m->readSettings();m->sequencer.running=true;for(int l=0;l<8;++l){m->sequencer.modulation.lanes[l].stage=0;m->sequencer.modulation.outputs[l]=2.f;}packets.clear();m->midiFrame=1234;m->processMx(args,true);
        require(packets.size()==8,"MIDI MX publishes all eight controllers without a physical MX");for(int l=0;l<8;++l)require(packets[l].bytes==std::vector<uint8_t>({0xb2,uint8_t(102+l),64}) && packets[l].frame==1234,"native MIDI MX uses CC102..109 and programmed stage values with sample timestamps");
        packets.clear();for(int f=0;f<100;++f)m->processMx(args,false);require(packets.empty(),"held MIDI MX gates do not flood unchanged CC values");
        m->params[M::modParam(0,M::MOD_VALUE)].setValue(5);m->readSettings();m->sequencer.modulation.outputs[0]=1.6f;m->processMx(args,true);require(packets.size()==1 && packets[0].bytes==std::vector<uint8_t>({0xb2,102,127}),"ramped audible voltage uses programmed destination stage for MIDI value");
        packets.clear();m->params[M::MIDI_MX_OUTPUT].setValue(1);m->processMx(args,true);require(packets.size()==16,"switching MX from CC to Note first releases all eight old controllers");for(int l=0;l<8;++l){require(packets[l].bytes==std::vector<uint8_t>({0xb2,uint8_t(102+l),0}),"old CC bus releases before notes");require(packets[8+l].bytes==std::vector<uint8_t>({0x92,uint8_t(35+l),uint8_t(l?64:127)}),"native MX notes35..42 carry stage velocity");}
        packets.clear();m->params[M::MIDI_MX_CHANNEL].setValue(16);m->processMx(args,true);require(packets.size()==16,"channel rebind releases and recreates all held notes");for(int l=0;l<8;++l)require(packets[l].bytes[0]==0x82 && packets[8+l].bytes[0]==0x9f,"MX rebind releases original channel before using channel16");
        packets.clear();m->midiPanic();m->midiMxOutput.suppressHeld();m->processMx(args,true);require(packets.size()==8,"native panic releases notes and suppresses the same held MX gates");packets.clear();m->sequencer.modulation.outputs.fill(0);m->processMx(args,true);m->sequencer.modulation.outputs.fill(5);m->processMx(args,true);require(packets.size()==8,"fresh MX edges resume after panic");packets.clear();m->onRemove(Module::RemoveEvent{});require(packets.size()>=8,"removing native module releases MIDI MX notes");
    }
    // Complete settings and bank import through Rack's real module loader.
    rack::plugin::Plugin plugin;plugin.slug="MetropolixLab";modelMetropolix->plugin=&plugin;modelMetropolix->slug="Metropolix";plugin.models.push_back(modelMetropolix);rack::plugin::plugins.push_back(&plugin);
    auto source=make(),copy=make();source->model=copy->model=modelMetropolix;source->id=865;copy->id=866;
    Json original(APP->engine->moduleToJson(source.get()));std::string error;Scope scope=Settings;int migrations=0;
    for(int cursor=0;cursor<17;++cursor)for(int field=0;field<2;++field){Json module(json_deep_copy(original.get()));auto* data=json_object_get(module.get(),"data");json_object_set_new(data,"schemaVersion",json_integer(34));json_object_set_new(data,"setupCursor",json_integer(cursor));json_object_set_new(data,"uiPage",json_integer(M::SETUP_PAGE));json_object_set_new(data,"uiField",json_integer(field));auto* p=json_object_get(module.get(),"params");while(json_array_size(p)>787)json_array_remove(p,json_array_size(p)-1);Json backup(capture(module.get(),Settings)),before,after;copy->params[M::MIDI_MX_CHANNEL].setValue(16);copy->params[M::MIDI_MX_OUTPUT].setValue(1);require(restore(copy.get(),backup.get(),before,after,error),"all17 released schema34 SETUP entries import");require(copy->setupCursor.load()==cursor+(cursor>=13?2:0) && copy->uiField.load()==field,"schema34 cursors preserve the selected setting after two insertions");require(!copy->integer(M::MIDI_MX_CHANNEL) && !copy->integer(M::MIDI_MX_OUTPUT),"legacy settings default the absent MX bus to disabled CC");++migrations;}
    for(int cursor=0;cursor<6;++cursor){Json data(source->dataToJson());json_object_set_new(data.get(),"schemaVersion",json_integer(34));json_object_set_new(data.get(),"midiSetupCursor",json_integer(cursor));copy->dataFromJson(data.get());require(copy->midiSetupCursor.load()==cursor+(cursor>=4?2:0),"old MIDI menu selection survives two inserted settings");}
    for(int schema:{22,26,34,35})for(json_int_t raw:{json_int_t(2147483647),json_int_t(9223372036854775807LL),json_int_t(-9223372036854775807LL)}){Json damaged(source->dataToJson());json_object_set_new(damaged.get(),"schemaVersion",json_integer(schema));for(const char* key:{"midiSetupCursor","setupCursor","modMenuCursor","trackMenuCursor"})json_object_set_new(damaged.get(),key,json_integer(raw));copy->dataFromJson(damaged.get());require(copy->midiSetupCursor.load()>=0 && copy->midiSetupCursor.load()<8 && copy->setupCursor.load()>=0 && copy->setupCursor.load()<19 && copy->modMenuCursor.load()>=0 && copy->modMenuCursor.load()<4 && copy->trackMenuCursor.load()>=0 && copy->trackMenuCursor.load()<16,"extreme damaged menu indices clamp before additive migration without signed overflow");if(schema==34 && raw>0)require(copy->setupCursor.load()==18 && copy->midiSetupCursor.load()==7,"large positive legacy indices consistently clamp to their last named entry");}
    source->params[M::OUTPUT_SOURCE_A].setValue(38);source->params[M::OUTPUT_SOURCE_B].setValue(39);source->putPreset(0,source->capturePreset());Json data(source->dataToJson());copy->dataFromJson(data.get());require(copy->getPreset(0).values[M::presetIndex(M::OUTPUT_SOURCE_A)]==38 && copy->getPreset(0).values[M::presetIndex(M::OUTPUT_SOURCE_B)]==39,"format12 preserves both new trigger routes in bank slots");json_object_set_new(data.get(),"presetFormat",json_integer(11));copy->dataFromJson(data.get());require(copy->getPreset(0).values[M::presetIndex(M::OUTPUT_SOURCE_A)]==37 && copy->getPreset(0).values[M::presetIndex(M::OUTPUT_SOURCE_B)]==37,"format11 keeps its original maximum route when sanitizing out-of-range values");
    Json module(APP->engine->moduleToJson(source.get())),backup(capture(module.get(),All));require(validate(copy.get(),backup.get(),scope,error),"schema35 format12 all-backup validates new settings and routes");Json old(json_deep_copy(backup.get()));json_object_set_new(json_object_get(old.get(),"state"),"schemaVersion",json_integer(34));require(!validate(copy.get(),old.get(),scope,error),"new fields cannot masquerade as a787-field legacy settings file");
    Json bank(captureSelected(module.get(),0));json_object_set_new(json_object_get(bank.get(),"bank"),"presetFormat",json_integer(11));require(!validate(copy.get(),bank.get(),scope,error),"legacy bank validation rejects new routes instead of silently accepting a future enum");
    rack::plugin::plugins.pop_back();plugin.models.clear();modelMetropolix->plugin=nullptr;
    std::cout<<"PASS: firmware1.6.5 native A/B triggers, expander-free MIDI MX, stage values, panic/rebind, "<<migrations<<" schema34 navigation migrations and format12 compatibility\n";
}
